	.text
	.globl	main
	.p2align	2
	.type	main,@function
main:                                   // @main
	.cfi_startproc
	stp	x29, x30, [sp, #-32]!           // Allocate 32 bytes on stack (original 16 + space if needed)
	.cfi_def_cfa_offset 32
	mov	x29, sp
	.cfi_def_cfa w29, 32
	.cfi_offset w30, -8
	.cfi_offset w29, -16

	// --- SVE Initialization ---
	rdvl	x19, #1             // x19 = Vector Length (VL) in bytes
	lsr	x20, x19, #2        // x20 = Number of 32-bit elements (VL / 4)

	// --- Original Initialization ---
	mov	w1, wzr             // w1 = ans = 0 (using x1 for GPR clarity where needed)
	mov	w8, wzr             // w8 = i = 0
	mov	x7, #1              // x7 = Constant 1 (for index increment and SVE dup)
	dup	z7.s, x7            // z7.s = vector of [1, 1, ...]

	// --- Outer Loops (i, j, k) ---
.L_i_loop:                              // Loop for i from 0 to 50
	mov	w10, w8             // w10 = current i
	mul	w_ii, w10, w10      // w_ii = i * i

	mov	w11, w10            // w11 = j = i
.L_j_loop:                              // Loop for j from i to 50
	cmp	w11, #51
	b.ge	.L_j_done           // Exit j loop if j >= 51

	mul	w_jj, w11, w11      // w_jj = j * j
	sub	w_i_j, w10, w11     // w_i_j = i - j
	mul	w_ijij, w_i_j, w_i_j  // w_ijij = (i - j)^2

	// Broadcast scalar values needed inside k loop to SVE vectors
	dup	z_jj.s, w_jj        // z_jj vector = [j*j, j*j, ...]
	dup	z_ijij.s, w_ijij    // z_ijij vector = [(i-j)^2, (i-j)^2, ...]

	mov	w12, wzr            // w12 = k = 0
.L_k_loop:                              // Loop for k from 0 to 50
	cmp	w12, #51
	b.ge	.L_k_done           // Exit k loop if k >= 51

	// Calculate k*k + i*i
	// mad can be used: w_kkii = w_ii + w12 * w12
	mov w_kkii, w_ii            // Start with i*i
	madd w_kkii, w12, w12, w_kkii // w_kkii = (k*k) + w_kkii

	// Replicate the complex start/end logic for the inner check loop
	// w2 = (i == j) ? k : 0; w16 = min(w2, 50) + 1;
	cmp	w10, w11            // Compare i, j
	csel	w2, w12, wzr, eq    // w2 = (i == j) ? k : 0
	mov	w9, #50             // Constant 50
	cmp	w2, w9              // Compare w2, 50
	csel	w16, w2, w9, hi     // w16 = min(w2, 50)
	add	w16, w16, #1        // w16 = min(w2, 50) + 1

	// Inner check loop: iterates idx from w2 up to (but not including) w16
	// SVE implementation replaces the NEON and scalar remainder loops
	mov	x2, xzr             // x2 = accumulator for this k iteration's count
	mov	x3, x2              // x3 = current idx, starts at w2 (as 64-bit GPR)
	mov	x16, x16            // x16 = limit idx (as 64-bit GPR)

	// Broadcast values constant within the SVE loop
	dup	z_kkii.s, w_kkii    // z_kkii vector = [k*k+i*i, ...]
	dup	z_k.s, w12          // z_k vector = [k, k, ...]

.L_sve_loop:
	// Check if idx >= limit before generating predicate
	cmp	x3, x16
	b.ge	.L_sve_done

	// Generate predicate for active lanes: idx < limit
	// ptrue implicitly uses ALL pattern here for whilelt context
	whilelt	p0.s, x3, x16       // p0 = active where element_index < (limit - idx) / step

	// Generate indices for active lanes: [idx, idx+1, idx+2, ...]
	// Use x7 (which holds 1) as the increment step
	index	z_idx.s, x3, x7     // z_idx = [x3, x3+1, x3+2, ...]

	// Calculate idx*idx for active lanes
	// Use a temporary register, e.g., z0
	mul	z0.s, p0/m, z_idx.s, z_idx.s // z0 = idx*idx

	// Calculate k-idx for active lanes
	// Use another temporary register, e.g., z1
	sub	z1.s, p0/m, z_k.s, z_idx.s   // z1 = k - idx

	// Calculate (k-idx)^2 for active lanes
	// Use another temporary register, e.g., z2
	mul	z2.s, p0/m, z1.s, z1.s       // z2 = (k-idx)^2

	// Check condition 1: idx*idx + j*j == k*k + i*i
	// Use z_tmp1 (e.g. z3) = z0 (idx*idx) + z_jj (j*j)
	// Use movprfx hint for the destructive add
	movprfx z3, p0/m, z0
	add	z3.s, p0/m, z3.s, z_jj.s    // z3 = idx*idx + j*j
	cmpeq	p1.s, p0/z, z3.s, z_kkii.s  // p1 = (z3 == z_kkii) ? T : F (inactive if p0 false)

	// Check condition 2: (k-idx)^2 + (i-j)^2 == k*k + i*i
	// Use z_tmp2 (e.g. z4) = z2 ((k-idx)^2) + z_ijij ((i-j)^2)
	// Use movprfx hint for the destructive add
	movprfx z4, p0/m, z2
	add	z4.s, p0/m, z4.s, z_ijij.s  // z4 = (k-idx)^2 + (i-j)^2
	cmpeq	p2.s, p0/z, z4.s, z_kkii.s  // p2 = (z4 == z_kkii) ? T : F (inactive if p0 false)

	// Combine conditions: p1 = p1 && p2 (under p0 mask)
	// The comparison results p1, p2 are already masked by p0/z
	and	p1.b, p0/z, p1.b, p2.b      // p1 = condition1 && condition2

	// Count matches in this iteration
	// Create a vector mask of 0s and 1s from predicate p1
	mov	z31.s, #0                   // Zero out mask register z31 (assuming z31 is temporary)
	// sel: Selects elements from first source (z7 = all 1s) if predicate p1 is true,
	// otherwise selects elements from second source (z31 = all 0s).
	sel	z31.s, p1, z7.s, z31.s      // z31 = (p1[i] ? 1 : 0)

	// Reduce the mask vector: sum all active elements (governed by p0)
	// uaddv: Unsigned Add Reduction to Scalar
	uaddv	d0, p0, z31.s               // d0 = horizontal sum of active elements in z31
	fmov	x4, d0                      // x4 = scalar sum for this iteration

	// Add count for this iteration to the k-loop accumulator (x2)
	add	x2, x2, x4

	// Update index for the next SVE iteration: advance by vector length in elements
	add	x3, x3, x20                 // idx = idx + VL_elems

	b	.L_sve_loop

.L_sve_done:
	// Add the accumulated count (x2) for this k to the total answer (w1)
	add	w1, w1, w2                  // ans = ans + x2

	add	w12, w12, #1                // k++
	b	.L_k_loop
.L_k_done:

	add	w11, w11, #1                // j++
	b	.L_j_loop
.L_j_done:

	add	w8, w8, #1                  // i++
	cmp	w8, #51
	b.ne	.L_i_loop

	// --- Print Result ---
	adrp	x0, .L.str
	add	x0, x0, :lo12:.L.str    // x0 = address of format string "%i\n"
	sxtw	x1, w1              // x1 = sign-extended result (w1)
	bl	printf

	// --- Function Epilogue ---
	mov	w0, wzr                 // Return 0 from main
	ldp	x29, x30, [sp], #32 // Restore stack pointer and registers
	.cfi_def_cfa_offset 0
	.cfi_restore w30
	.cfi_restore w29
	ret
.Lfunc_end1:
	.size	main, .Lfunc_end1-main
	.cfi_endproc
                                        // -- End function
	.type	.L.str,@object                  // @.str
	.section	.rodata.str1.1,"aMS",@progbits,1
.L.str:
	.asciz	"%i\n"
	.size	.L.str, 4

	.ident	"Translated to AArch64+SVE" // Add identifier if desired
	.section	".note.GNU-stack","",@progbits
	.addrsig

