	// Use z_tmp2 (e.g. z4) = z2 ((k-idx)^2) + z9 (z_ijij = (i-j)^2)
	// Use movprfx hint for the destructive add, requires size suffix .s
	movprfx z4.s, p0/m, z2.s    // Prepare z4 with active elements from z2
	add	z4.s, p0/m, z4.s, z9.s  // z4 = (k-idx)^2 + (i-j)^2 (Using z9)
	cmpeq	p2.s, p0/z, z4.s, z10.s  // p2 = (z4 == z_kkii) ? T : F (Using z10)

