	add	w1, w1, w2                  // ans = ans + count_for_k (using w2 as lower 32b of x2)

	add	w12, w12, #1                // k++
	b	.L_k_loop
.L_k_done:

	add	w11, w11, #1                // j++
	b	.L_j_loop
