	// add: Vector add.
	// p0/m: Governed by predicate p0, with merging for inactive lanes.
	// Adds z1 to z0 only where p0 is true; inactive lanes in z0 remain unchanged
	// (they were initialized to 0 and remain 0 due to the /z on ld1d).
	add	z0.d, p0/m, z0.d, z1.d          // z0 += z1 for active lanes

