	// ptrue: Set Predicate True. Sets all lanes of P0 active for the specified size (.d).
	// This is necessary because 'uaddv' operates based on the predicate.
	// It's safe to activate all lanes because inactive lanes in z0 are guaranteed
	// to be 0 from the ld1d zeroing and the initial mov z0.d, #0.
	ptrue	p0.d                            // p0 = predicate with all lanes active for doublewords
